"""Independent probability explanations, worked examples and complete short checks."""
from fractions import Fraction as F
from itertools import product
import re
import sympy as s
from s1_representation_teaching import table
lessons,questions,models=[],[],[]
def tex(v):return s.latex(s.Rational(v.numerator,v.denominator) if isinstance(v,F) else s.sympify(v))
def math(v):return r'\('+(r'\mathrm '+v if isinstance(v,str) and v.startswith('P(') else tex(v))+r'\)'
def picture(name,alt):return '<p><img src="/assets/original/s1-probability/'+name+'.svg" alt="'+alt+'"></p>'
def ex(title,question,solution,key):return dict(title=title,question=question,solution=solution,verification=key)
def lesson(key,title,summary,ideas,mistakes,examples):
 lessons.append(dict(key=key,id='orig_9709_s1_prob_'+key,title=title,summary=summary,objective=summary,before='<p>Use exact fractions and identify what is selected at random. Counting-selections questions refer to the next chapter; the combination notation used there is introduced briefly in the final lesson.</p>',ideas=ideas,method='<ol><li>Define outcomes, events and any condition before calculating.</li><li>Decide which outcomes are equally likely and which branch probabilities change.</li><li>Multiply along a path and add only disjoint qualifying paths.</li><li>For a conditional probability, restrict both numerator and denominator to the stated condition.</li><li>Check probability bounds, all branches and original model restrictions.</li></ol>',mistakes=mistakes,examples=examples))

lesson('sample_spaces','Sample spaces, complements and event relations',
 'Build an appropriate outcome space and distinguish inclusive or, exactly one, mutually exclusive and independent.',
 r'''<h3>Choose the elementary outcomes first</h3><p>An event is a set of outcomes. If these outcomes really are equally likely, its probability is the favourable count divided by the total count. Independence and fair individual trials do not make their possible totals equally likely. Keep order when a first and a second result are distinguishable.</p>'''+picture('sample-grid','Six of sixteen ordered pairs from fair four-sector spinners have total at least six')+r'''
 <h3>Union, intersection and complement</h3><p>\(A\cup B\) means A or B or both; \(A\cap B\) means both; \(A^{\prime}\) means not A.</p>\[\mathrm P(A^{\prime})=1-\mathrm P(A).\]\[\begin{aligned}\mathrm P(A\cup B)&=\mathrm P(A)+\mathrm P(B)\\&\quad-\mathrm P(A\cap B).\end{aligned}\]<p>For exactly one, add the two non-overlapping A-only and B-only regions. Neither is the complement of the union.</p>
 <h3>Mutual exclusion is not independence</h3><p>Mutually exclusive events cannot occur together. Independence instead requires \(\mathrm P(A\cap B)=\mathrm P(A)\mathrm P(B)\). Two disjoint events with positive probabilities are dependent: the intersection is zero but the product is positive. If an event has probability zero, that shortcut needs separate care.</p>
 <h3>Use weights for biased trials</h3><p>For independent biased spins multiply the relevant individual probabilities for each ordered pair, then add qualifying pairs. Do not divide by the number of listed pairs unless their weights are equal.</p>''',
 ['Possible totals are not usually equally likely.','Inclusive or includes the intersection once.','Exactly one excludes the intersection.','Positive mutually exclusive events are dependent.'],[
 ex('Count ordered pairs rather than possible totals',r'<p>Two fair four-sector spinners labelled 1 to 4 are spun independently. Let A mean total at least 6 and B mean equal scores. Find \(\mathrm P(A)\), \(\mathrm P(B)\) and \(\mathrm P(B\mid A)\).</p>',r'<p>There are 16 equally likely ordered pairs. Six have total at least 6, four have equal scores, and (3,3), (4,4) satisfy both.</p>\[\begin{aligned}\mathrm P(A)&=3/8,\\\mathrm P(B)&=1/4,\\\mathrm P(B\mid A)&=2/6=1/3.\end{aligned}\]','PROB-PAIRS'),
 ex('Keep the four disjoint regions separate',r'<p>\(\mathrm P(A)=3/5\), \(\mathrm P(B)=1/2\), \(\mathrm P(A\cap B)=1/4\). Find the four Venn-region probabilities and the probability of exactly one event.</p>',r'\[\begin{aligned}\mathrm P(A\cap B^{\prime})&=7/20,\\\mathrm P(A\cap B)&=1/4,\\\mathrm P(A^{\prime}\cap B)&=1/4,\\\mathrm P(A^{\prime}\cap B^{\prime})&=3/20.\end{aligned}\]<p>Exactly one has probability \(7/20+1/4=3/5\). The four regions sum to 1.</p>'+picture('venn-regions','A-only 7/20, intersection 1/4, B-only 1/4 and neither 3/20'),'PROB-VENN'),
 ex('Disjoint positive events cannot be independent',r'<p>A and B are mutually exclusive with probabilities 2/5 and 1/3. Find the union probability and decide whether they are independent.</p>',r'\[\mathrm P(A\cup B)=2/5+1/3=11/15.\]<p>The intersection is zero, whereas \(\mathrm P(A)\mathrm P(B)=2/15\). They are not independent. Mutual exclusion justifies adding here, not multiplying.</p>','PROB-DISJOINT'),
 ex('A biased spinner needs weighted outcomes',r'<p>A spinner scores 1, 2, 4 with probabilities 1/2, 1/3, 1/6. Spin twice independently. Given at least one 4, find the probability that the total is 5.</p>',r'''<p>Let E mean total 5 and H mean at least one 4. Only (1,4) and (4,1) contribute to E.</p>\[\begin{aligned}\mathrm P(E)&=2(1/2)(1/6)=1/6,\\\mathrm P(H)&=1-(5/6)^2=11/36,\\\mathrm P(E\mid H)&=\frac{1/6}{11/36}=6/11.\end{aligned}\]''','PROB-BIASED')])

lesson('finite_sequences','Independent trials, sequences and stopping rules',
 'Add complete disjoint sequences, using complements where useful and stopping paths when the experiment ends.',
 r'''<h3>Multiply independent trials, not arbitrary events</h3><p>For independent events, multiply their probabilities for a joint occurrence. Independence is a model assumption to state or a property to prove, not a consequence of events having different names.</p>
 <h3>Exactly one requires its possible positions</h3><p>In three independent trials with success chance p, exactly one success consists of SFF, FSF and FFS. These paths are disjoint. At least one is often easier as one minus the all-failure probability. For unequal trial chances calculate each path separately.</p>
 <h3>Do not extend a path after stopping</h3><p>In a first-to-two contest the terminal paths for A are AA, ABA and BAA. AABA is not a valid additional terminal path: the contest has already finished. Similarly, testing different keys without repeating them changes the next conditional success chance after each failure.</p>
 <h3>Finite dependence can still use a tree</h3><p>If a later probability depends on the preceding result, label each reached branch with that conditional probability. A finite tree is enough; neither a constant success probability nor an infinite distribution should be assumed.</p>''',
 ['At least one is not the same as exactly one.','Account for every position of a specified result.','Successive probabilities may differ.','Stop a sequence as soon as its stopping condition is met.'],[
 ex('Three checks with unequal probabilities',r'<p>Independent checks have pass probabilities 3/4, 2/3 and 4/5. Find the probabilities of all passing, exactly two passing and at least one passing.</p>',r'\[\mathrm P(\text{all})=(3/4)(2/3)(4/5)=2/5.\]<p>Exactly two consists of PPF, PFP and FPP, with probabilities 1/10, 1/5, 2/15.</p>\[\begin{aligned}\mathrm P(\text{exactly two})&=13/30,\\\mathrm P(\text{at least one})&=1-(1/4)(1/3)(1/5)\\&=59/60.\end{aligned}\]','PROB-CHECKS'),
 ex('Exactly one and at least two use different paths',r'<p>Three independent signals are red with probability 2/5 each. Find the probabilities of exactly one red and at least two reds.</p>',r'''\[\begin{gathered}\mathrm P(\text{exactly one})\\=3(2/5)(3/5)^2=54/125.\end{gathered}\]<p>At least two includes three paths with two reds and one path with three.</p>\[\mathrm P(\text{at least two})=44/125.\]''','PROB-POSITIONS'),
 ex('A failed key is not tried again',r'<p>One of six keys opens a lock. Keys are tried uniformly at random without repeats, stopping on success or after four tries. Given success but not on the first try, find the chance of success on the fourth.</p>',r'''<p>The opening key is equally likely to occupy any of the six positions in a random ordering. Success within four tries has probability 4/6. Under the stated condition only positions 2, 3, 4 remain, equally likely.</p>\[\begin{gathered}\mathrm P(\text{fourth}\mid\text{success, not first})\\=1/3.\end{gathered}\]<p>A tree gives reached success chances 1/6, 1/5, 1/4, 1/3; they must not all be 1/6.</p>''','PROB-KEYS'),
 ex('A first-to-two contest has three winning paths',r'<p>A wins each round independently with probability 3/5. The contest ends when either player wins twice. Find A’s win probability and, given an A win, the chance of three rounds.</p>',r'''<p>Let W mean an A win and L mean three rounds. A wins on AA, ABA or BAA.</p>\[\begin{aligned}\mathrm P(W)&=9/25+2(18/125)\\&=81/125,\\\mathrm P(L\mid W)&=36/81=4/9.\end{aligned}\]''','PROB-CONTEST')])

lesson('tables_conditioning','Two-way tables, conditioning and independence',
 'Use the conditioning group as denominator, recover missing cells, and justify independence numerically.',
 r'''<h3>The condition changes the denominator</h3>\[\mathrm P(A\mid B)=\frac{\mathrm P(A\cap B)}{\mathrm P(B)}.\]<p>This requires \(\mathrm P(B)>0\). In a frequency table the denominator is the number in B, not the grand total or the number in A. In general \(\mathrm P(A\mid B)\) and \(\mathrm P(B\mid A)\) differ.</p>
 <h3>Complete cells and margins consistently</h3><p>Intersection, A-only, B-only and neither are disjoint cells. Row and column totals overlap, so adding them directly double-counts the intersection. Every recovered count must be a non-negative integer.</p>
 <h3>Test independence using the actual marginals</h3><p>Compare the joint probability with the product of the marginals. Equivalently compare a conditional with its marginal when that conditional is defined. Give the two numerical values, rather than just saying that the events look unrelated.</p>
 <h3>Use one joint event in both conditionals</h3>\[\begin{aligned}\mathrm P(A\cap B)&=\mathrm P(A)\mathrm P(B\mid A),\\\mathrm P(B)&=\frac{\mathrm P(A\cap B)}{\mathrm P(A\mid B)}.\end{aligned}\]<p>The second expression needs a positive denominator. Restore the four cells and check they are all non-negative after solving a reverse problem.</p>''',
 ['The conditional denominator is the conditioning group.','Do not reverse the direction of a conditional.','Marginal totals overlap.','An independence claim needs a numerical check.'],[
 ex('Read the direction of a conditional',table(['','Morning','Afternoon'],[['Attends club',12,8],['Does not attend',6,14]])+r'<p>A person is selected uniformly. Find \(\mathrm P(\text{attends}\mid\text{morning})\) and its reverse. Are the events independent?</p>',r'\[\begin{aligned}\mathrm P(\text{attends}\mid\text{morning})&=12/18=2/3,\\\mathrm P(\text{morning}\mid\text{attends})&=12/20=3/5.\end{aligned}\]<p>The joint is 3/10, but the marginal product is \((1/2)(9/20)=9/40\). The events are dependent.</p>','PROB-TABLE'),
 ex('Recover all four table cells',r'<p>Among 60 items, 24 have A, 30 have B, and 9 have both. Find A-only, B-only, neither and the probability of exactly one characteristic for a uniform selection.</p>',r'''<p>The cells are A-only=15, both=9, B-only=21, neither=15. They total 60.</p>\[\begin{gathered}\mathrm P(\text{exactly one})\\=\frac{15+21}{60}=3/5.\end{gathered}\]''','PROB-CELLS'),
 ex('An independence condition recovers a missing count',table(['','B','Not B'],[['A',6,4],['Not A',9,'n']])+r'<p>The two classifications are independent for a uniform selection. Find n and the union probability.</p>',r'\[\frac{6}{19+n}=\frac{10}{19+n}\frac{15}{19+n}.\]<p>Thus 6(19+n)=150, so n=6. All four counts are non-negative integers.</p>\[\mathrm P(A\cup B)=1-6/25=19/25.\]','PROB-UNKNOWN-CELL'),
 ex('Two conditionals share the same intersection',r'<p>\(\mathrm P(A)=2/5\), \(\mathrm P(B\mid A)=3/4\), \(\mathrm P(A\mid B)=3/5\). Find \(\mathrm P(B)\) and the probability of exactly one event.</p>',r'\[\begin{aligned}\mathrm P(A\cap B)&=(2/5)(3/4)=3/10,\\\mathrm P(B)&=(3/10)/(3/5)=1/2,\\\mathrm P(\text{exactly one})&=2/5+1/2-2(3/10)\\&=3/10.\end{aligned}\]','PROB-REVERSE-CONDITIONAL')])

lesson('tree_mixtures','Trees, total probability and reverse conditioning',
 'Weight every route through a mixture and distinguish independence within a group from independence after mixing.',
 r'''<h3>Choose the population, then the outcome</h3><p>If the first-stage groups G and G′ exhaust the possibilities,</p>\[\begin{aligned}\mathrm P(S)&=\mathrm P(G)\mathrm P(S\mid G)\\&\quad+\mathrm P(G^{\prime})\mathrm P(S\mid G^{\prime}).\end{aligned}\]<p>Group labels do not make groups equally likely. At every reached node, outgoing probabilities sum to 1; terminal path probabilities also sum to 1.</p>'''+picture('mixture-tree','A weighted tree with group probabilities one third and two thirds and different success chances')+r'''
 <h3>Reverse the condition through the joint event</h3>\[\mathrm P(G\mid S)=\frac{\mathrm P(G)\mathrm P(S\mid G)}{\mathrm P(S)}.\]<p>The denominator must include success through every possible group. Use the observed outcome to update the group probability; do not just report a forward branch.</p>
 <h3>Conditional independence can disappear after mixing</h3><p>Two tests may be independent within each production line while both share that unobserved line. Calculate the unconditional joint and compare it with the product of the unconditional marginals. Choosing one line once is different from choosing a fresh line before each test.</p>
 <h3>Recover an unknown branch or group weight</h3><p>Use the total-probability equation, then check the recovered value lies between 0 and 1 and reproduces the observed total. A zero denominator makes a conditional undefined, not zero.</p>''',
 ['Weight groups by their actual selection probabilities.','A posterior is not its forward branch.','The denominator includes all routes to the observed outcome.','Independence within groups does not imply independence after mixing.'],[
 ex('A weighted choice changes the observed mixture',r'<p>Container A is chosen with probability 1/3, B otherwise. Their red proportions are 3/4 and 2/5. One counter is selected uniformly from the chosen container. Find the red probability and the chance of A given red.</p>',r'\[\begin{aligned}\mathrm P(R)&=(1/3)(3/4)+(2/3)(2/5)\\&=31/60,\\\mathrm P(A\mid R)&=(1/4)/(31/60)=15/31.\end{aligned}\]','PROB-MIXTURE'),
 ex('Recover an unknown success branch',r'<p>A route A is chosen with probability 2/5. It succeeds with probability 3/4. The other route succeeds with probability q. Overall success has probability 3/5. Find q.</p>',r'\[(2/5)(3/4)+(3/5)q=3/5.\]<p>Thus q=1/2. It lies in [0,1] and reproduces the given success probability.</p>','PROB-UNKNOWN-BRANCH'),
 ex('Independent inside each line, dependent overall',r'<p>A component comes from A with probability 1/4, B otherwise. Conditional on the line, two tests are independent, each with pass chance 4/5 on A and 2/5 on B. Find the marginal and joint pass probabilities, then update the line probability after two passes.</p>',r'''\[\mathrm P(P_1)=1/5+3/10=1/2.\]\[\mathrm P(P_1\cap P_2)=4/25+3/25=7/25.\]\[\begin{aligned}\mathrm P(A\mid P_1\cap P_2)&=\frac{4/25}{7/25}\\&=4/7.\end{aligned}\]<p>The two pass events are dependent overall because 7/25 differs from 1/4. Each term in the joint first weights the appropriate line, then multiplies its two conditional pass chances.</p>''','PROB-CONDITIONAL-INDEPENDENCE'),
 ex('A rare observation updates a source proportion',r'<p>Source A has defect probability 1/10; B has defect probability 1/50. Overall defect probability is 1/25. Find the proportion from A and the chance that a defective item came from A.</p>',r'\[w/10+(1-w)/50=1/25.\]<p>Hence w=1/4.</p>\[\mathrm P(A\mid D)=(1/40)/(1/25)=5/8.\]<p>The posterior 5/8 is different from the prior 1/4 and from the forward defect probability 1/10.</p>','PROB-BASE-RATE')])

lesson('changing_samples','Without replacement, transfers and changing contents',
 'Track colour counts and denominators at each step, retaining stopping rules and the exact object identity when relevant.',
 r'''<h3>Without replacement changes the next draw</h3><p>After a red is removed, both the red count and total fall by one. After a blue is removed, the red count is unchanged but the total still falls. Two colour orders can lead to the same final event; add their probabilities rather than keeping just one.</p>
 <h3>Transfers change the destination before its draw</h3><p>Write the destination counts after each possible transfer. If a named object is tracked, distinguish that identity from its colour. For a return transfer or a second cycle, carry forward the actual contents; do not reset unless instructed.</p>
 <h3>Replacement can depend on the first result</h3><p>If only one colour is returned, later denominators differ between branches. A single fixed fraction for the second draw would describe a different experiment. For a stopping game, include only paths on which the game has not already ended.</p>
 <h3>Unordered selections are a different sample space</h3>\[\binom nr=\frac{n!}{r!(n-r)!}.\]<p>This counts unordered r-subsets of n distinct objects. For a uniform selection without replacement, favourable subset counts can be divided by the total subset count. Do not mix an ordered favourable count with an unordered denominator. Questions using this notation are tagged with the Counting selections prerequisite from the next chapter.</p>''',
 ['Update both the colour count and the total when required.','A transferred object belongs to the destination before the next draw.','Colour and the identity of one named counter are different events.','Do not reset contents or extend a stopped game.'],[
 ex('Both red, exactly one red, or at least one red',r'<p>A bag has 3 red and 5 blue counters. Draw two uniformly without replacement. Find the probabilities of both red and exactly one red, then both red given at least one red.</p>',r'''<p>Let E mean exactly one red, and H mean at least one red.</p>\[\begin{aligned}\mathrm P(RR)&=(3/8)(2/7)=3/28,\\\mathrm P(E)&=2(3/8)(5/7)=15/28,\\\mathrm P(H)&=1-(5/8)(4/7)=9/14,\\\mathrm P(RR\mid H)&=\frac{3/28}{9/14}=1/6.\end{aligned}\]''','PROB-WITHOUT-REPLACEMENT'),
 ex('The destination changes after the transfer',r'<p>A holds 2 red, 3 blue; B holds 4 red, 2 blue. Move a uniform counter from A to B, then draw uniformly from B. Find the chance of a red draw from B and, given that red draw, the chance that the transfer was red.</p>',r'\[\begin{aligned}\mathrm P(R_2)&=(2/5)(5/7)+(3/5)(4/7)\\&=22/35,\\\mathrm P(R_1\mid R_2)&=(10/35)/(22/35)=5/11.\end{aligned}\]<p>B contains seven counters at its draw, whichever colour was transferred.</p>','PROB-TRANSFER'),
 ex('Return one colour, keep out the other',r'<p>A bag has 4 red and 3 blue counters. The first counter is returned if red and kept out if blue. Draw again uniformly. Find the chance of equal colours and the chance that the first was red given the second was blue.</p>',r'\[\begin{aligned}\mathrm P(\text{same})&=(4/7)^2+(3/7)(2/6)\\&=23/49,\\\mathrm P(B_2)&=(4/7)(3/7)+(3/7)(2/6)\\&=19/49,\\\mathrm P(R_1\mid B_2)&=(12/49)/(19/49)=12/19.\end{aligned}\]','PROB-CONDITIONAL-REPLACEMENT'),
 ex('Stop as soon as the second red appears',r'<p>A bag has 2 red and 2 blue counters. Draw uniformly without replacement until the second red appears. Find the chance of stopping on draw 3 and, under that condition, of a blue first draw.</p>',r'<p>The only terminal paths on draw 3 are RBR and BRR. Each has probability 1/6. RRB is not a path to a third draw because RR already stops the process.</p>\[\begin{aligned}\mathrm P(T=3)&=1/3,\\\mathrm P(B_1\mid T=3)&=(1/6)/(1/3)=1/2.\end{aligned}\]<p>As a check, the probabilities of stopping on draws 2, 3, 4 are 1/6, 1/3, 1/2, summing to 1.</p>','PROB-STOPPING')])

def field(key,label,value,**extra):return dict(key=key,label=label,type='number',expected=str(value),**extra)
def choice(key,label,value,options):return dict(key=key,label=label,type='choice',expected=value,options=options)
def quick(topic,family,v,title,prompt,fields,explanation,model):
 uid=f'M4U-9709-S1-PROB-CHECK-{topic.upper()}-{family}-{v}'
 answer=''.join('<p>'+f['label']+': '+(f['options'][f['expected']] if f['type']=='choice' else math(f['expected']))+'</p>' for f in fields)
 questions.append(dict(id=uid,family_uid=f'M4U-9709-S1-PROB-CHECK-{topic.upper()}-{family}',lesson=topic,title=title,collection='short' if v==0 else 'variant',prompt_html=prompt,answer_html=answer,solution_html='<p>'+explanation+'</p><h4>Complete answers</h4>'+answer,hint_html='<p>Define the condition and every qualifying path. Check the current contents, the denominator and whether all outcomes have equal weight.</p>',marks=len(fields),difficulty=2,fields=fields,parts=[dict(label='',marking_criteria=[dict(code='B1',marks=1,description_html='Complete correct answer for '+f['label']+'.') for f in fields])],verification=uid))
 models.append(dict(uid=uid,**model))

for v in range(2):
 n,target=(4,6) if v==0 else (5,8);count=sum(a+b>=target for a,b in product(range(1,n+1),repeat=2))
 quick('sample_spaces',1,v,'Count the ordered elementary outcomes',f'<p>Two independent fair {n}-sector spinners each show 1 to {n}. Find the number of ordered pairs with total at least {target}, the size of the whole ordered sample space, and the event probability.</p>',[field('count','Favourable ordered pairs',count),field('total','All ordered pairs',n*n),field('probability','Probability of the event',F(count,n*n))],'Count ordered pairs, not possible totals. All pairs are equally likely under this specified model.',dict(kind='pairs',n=n,target=target))
 a,b,j=(F(3,5),F(1,2),F(1,4)) if v==0 else (F(2,3),F(1,2),F(1,3))
 quick('sample_spaces',2,v,'Every disjoint Venn region is needed','<p>'+math(r'P(A)')+'='+math(a)+', '+math(r'P(B)')+'='+math(b)+', '+math(r'P(A\cap B)')+'='+math(j)+'. Give all four labelled region probabilities.</p>',[field('a_only','A only',a-j),field('both','Both A and B',j),field('b_only','B only',b-j),field('neither','Neither A nor B',1-a-b+j)],'Subtract the intersection from each marginal; use the complement of the union for neither. The four disjoint regions sum to one.',dict(kind='venn',a=str(a),b=str(b),joint=str(j)))
 a,b=F(2,5),F(1,3);j=F(0) if v==0 else a*b;condition='mutually exclusive' if v==0 else 'independent'
 quick('sample_spaces',3,v,'Do not confuse exclusion with independence',f'<p>A and B are {condition}, with probabilities 2/5 and 1/3. Give the intersection and union probabilities, and select whether they are independent.</p>',[field('joint','Intersection probability',j),field('union','Union probability',a+b-j),choice('choice','Independence conclusion','B' if v==0 else 'A',{'A':'Independent','B':'Dependent','C':'Cannot be determined from the stated model'})],'Compare the intersection with the product of the positive marginals. Disjoint positive events are dependent.',dict(kind='relation',a=str(a),b=str(b),independent=v==1))
 ps=[F(1,2),F(1,3),F(1,6)] if v==0 else [F(1,4),F(1,2),F(1,4)];num=2*ps[0]*ps[2];den=1-(1-ps[2])**2
 quick('sample_spaces',4,v,'Biased ordered outcomes need their weights',table(['Score','Probability'],list(zip([1,2,4],map(math,ps))))+'<p>Spin twice independently. Find the probability of total 5, of at least one 4, and of total 5 given at least one 4.</p>',[field('total_five','Probability of total 5',num),field('condition','Probability of at least one 4',den),field('conditional','Conditional probability',num/den)],'The numerator adds (1,4) and (4,1) with their weights. Divide by the probability of the condition, not the size of a list.',dict(kind='biased',probs=list(map(str,ps))))

 p=F(2,5) if v==0 else F(3,4);q=1-p
 quick('finite_sequences',1,v,'Exactly one success includes all its positions','<p>Three independent trials each succeed with probability '+math(p)+'. Find the probabilities of SFF, exactly one success, and at least one success.</p>',[field('first_only','Probability of SFF',p*q*q),field('exactly_one','Probability of exactly one success',3*p*q*q),field('at_least_one','Probability of at least one success',1-q**3)],'SFF, FSF and FFS are disjoint. At least one is the complement of FFF.',dict(kind='three_trials',p=str(p)))
 ps=[F(3,4),F(2,3),F(4,5)] if v==0 else [F(1,2),F(3,5),F(5,6)];allpass=ps[0]*ps[1]*ps[2];none=(1-ps[0])*(1-ps[1])*(1-ps[2]);two=sum((1-ps[i])*ps[(i+1)%3]*ps[(i+2)%3] for i in range(3))
 quick('finite_sequences',2,v,'Unequal trials require separate path weights','<p>Independent trials have success probabilities '+', '.join(map(math,ps))+'. Find the probabilities of all three successes, exactly two successes, and no successes.</p>',[field('all','All three successes',allpass),field('two','Exactly two successes',two),field('none','No successes',none)],'Enumerate the three locations of the single failure using each trial’s own probability.',dict(kind='unequal',probs=list(map(str,ps))))
 n,h=(6,4) if v==0 else (8,3)
 quick('finite_sequences',3,v,'Different keys are tried without repetition',f'<p>Exactly one of {n} keys works. Try keys uniformly without repeats, stopping on success or after {h} tries. Find the probability of success, of success on the last allowed try, and of the last try given success but not on the first.</p>',[field('success','Success within the allowed tries',F(h,n)),field('last','Success on the last allowed try',F(1,n)),field('conditional','Last try given success but not first',F(1,h-1))],'The opening key has a uniform position in a random ordering. Apply the stated condition to those positions.',dict(kind='keys',n=n,h=h))
 p=F(3,5) if v==0 else F(1,3);q=1-p;win=p*p+2*p*p*q
 quick('finite_sequences',4,v,'Terminal paths of a first-to-two contest','<p>A wins each round independently with probability '+math(p)+'. Play stops when either player has two wins. Find A’s win probability, the chance of exactly two rounds, and the chance of three rounds given an A win.</p>',[field('win','Probability A wins',win),field('two','Probability of exactly two rounds',p*p+q*q),field('conditional','Three rounds given A wins',2*p*p*q/win)],'For an A win use AA, ABA and BAA only. A path ending earlier cannot be extended.',dict(kind='contest',p=str(p)))

 cells=[12,8,6,14] if v==0 else [9,15,3,13];a,b,c,d=cells;N=sum(cells)
 quick('tables_conditioning',1,v,'Read a conditional in its stated direction',table(['','B','Not B'],[['A',a,b],['Not A',c,d]])+r'<p>One item is selected uniformly. Find \(P(A\mid B)\), \(P(B\mid A)\) and \(P(A\cap B)\).</p>',[field('a_given_b','Probability of A given B',F(a,a+c)),field('b_given_a','Probability of B given A',F(a,a+b)),field('joint','Joint probability',F(a,N))],'Use the conditioning column or row as denominator; only the joint uses the grand total.',dict(kind='table',cells=cells))
 N,A,B,J=(60,24,30,9) if v==0 else (80,35,32,14)
 quick('tables_conditioning',2,v,'Recover the missing cells before conditioning',f'<p>Of {N} items, {A} have A, {B} have B and {J} have both. Find A-only, B-only and neither counts, then P(B given A) for a uniform selection.</p>',[field('a_only','A-only count',A-J),field('b_only','B-only count',B-J),field('neither','Neither count',N-A-B+J),field('conditional','Probability of B given A',F(J,A))],'The marginal totals include the shared cell. Subtract it before forming the disjoint cells.',dict(kind='marginals',N=N,A=A,B=B,J=J))
 a,b,c=(6,4,9) if v==0 else (8,12,6);d=F(b*c,a);N=a+b+c+d
 quick('tables_conditioning',3,v,'Independence fixes an unknown table entry',table(['','B','Not B'],[['A',a,b],['Not A',c,'n']])+r'<p>A uniform selection has independent classifications. Find the positive integer n, the probability of exactly one characteristic, and \(P(A\mid B)\).</p>',[field('unknown','Missing count n',d),field('xor','Probability of exactly one characteristic',F(b+c,N)),field('conditional','Probability of A given B',F(a,a+c))],'Use the joint/marginal equation with the unknown in the grand total. Check the recovered count and all cells.',dict(kind='unknown_table',a=a,b=b,c=c))
 a,ba,ab=(F(2,5),F(3,4),F(3,5)) if v==0 else (F(3,7),F(2,3),F(1,2));j=a*ba;b=j/ab
 quick('tables_conditioning',4,v,'Recover a marginal from two directions','<p>'+math(r'P(A)')+'='+math(a)+', '+math(r'P(B\mid A)')+'='+math(ba)+', '+math(r'P(A\mid B)')+'='+math(ab)+'. Find the joint, P(B), and the probability of exactly one event.</p>',[field('joint','Joint probability',j),field('b','Probability of B',b),field('xor','Probability of exactly one event',a+b-2*j)],'Both conditionals involve the same joint event. Recover that joint before solving for the missing marginal.',dict(kind='reverse',a=str(a),ba=str(ba),ab=str(ab)))

 w,a,b=(F(1,3),F(3,4),F(2,5)) if v==0 else (F(2,5),F(2,3),F(1,4));joint=w*a;total=joint+(1-w)*b
 quick('tree_mixtures',1,v,'All success routes belong in the denominator','<p>Choose group A with probability '+math(w)+', B otherwise. Success chances are '+math(a)+' on A and '+math(b)+' on B. Find the A-and-success joint, total success probability and P(A given success).</p>',[field('joint','Probability of A and success',joint),field('total','Total success probability',total),field('posterior','Probability of A given success',joint/total)],'Multiply along each route and add the disjoint success routes before reversing the condition.',dict(kind='mixture',w=str(w),a=str(a),b=str(b)))
 w,a,T=(F(2,5),F(3,4),F(3,5)) if v==0 else (F(1,4),F(2,3),F(5,12));b=(T-w*a)/(1-w);joint=(1-w)*b
 quick('tree_mixtures',2,v,'Recover an unknown branch and check its range','<p>Choose A with probability '+math(w)+'. Its success chance is '+math(a)+'. The other group has unknown success chance q. Overall success probability is '+math(T)+'. Find q, P(B and success), and P(B given success).</p>',[field('q','Unknown success chance q',b),field('joint','Probability of B and success',joint),field('posterior','Probability of B given success',joint/T)],'Use total probability to recover q, then check 0≤q≤1 and restore the observed total.',dict(kind='unknown_branch',w=str(w),a=str(a),total=str(T)))
 w,a,b=(F(1,4),F(4,5),F(2,5)) if v==0 else (F(1,3),F(3,4),F(1,4));m=w*a+(1-w)*b;j=w*a*a+(1-w)*b*b;opts={'A':'Independent after mixing','B':'Dependent after mixing','C':'The model does not determine the joint'} if v==0 else {'A':'Independent because they are independent in each group','B':'Impossible model: the branch chances are outside [0,1]','C':'Dependent after mixing'}
 quick('tree_mixtures',3,v,'Keep the same hidden group for both tests','<p>Choose group A once with probability '+math(w)+', B otherwise. Conditional on the group, two tests are independent, each with pass chance '+math(a)+' on A and '+math(b)+' on B. Find one-pass and both-pass probabilities, P(A given both passes), and decide unconditional independence.</p>',[field('marginal','One-pass probability',m),field('joint','Both-pass probability',j),field('posterior','Probability of A given both passes',w*a*a/j),choice('choice','Independence after mixing','B' if v==0 else 'C',opts)],'Keep the chosen group throughout both tests. Compare the unconditional joint with the square of the unconditional marginal.',dict(kind='hidden_group',w=str(w),a=str(a),b=str(b)))
 a,b,T=(F(1,10),F(1,50),F(1,25)) if v==0 else (F(1,5),F(1,20),F(1,10));w=(T-b)/(a-b);j=w*a
 quick('tree_mixtures',4,v,'A base rate must agree with the total','<p>A and B have defect chances '+math(a)+' and '+math(b)+'. Every item comes from exactly one source. Overall defect chance is '+math(T)+'. Find the proportion from A, P(A and defect), and P(A given defect).</p>',[field('weight','Proportion from A',w),field('joint','Probability of A and defect',j),field('posterior','Probability of A given defect',j/T)],'Solve the mixture equation before conditioning. A source proportion and a defect chance have different roles.',dict(kind='unknown_weight',a=str(a),b=str(b),total=str(T)))

 R,B=(3,5) if v==0 else (4,3);N=R+B;rr=F(R,N)*F(R-1,N-1);one=2*F(R,N)*F(B,N-1)
 quick('changing_samples',1,v,'Without replacement has two different denominators',f'<p>Draw two counters uniformly without replacement from {R} red and {B} blue. Find both-red and exactly-one-red probabilities, then both red given at least one red.</p>',[field('rr','Probability both are red',rr),field('one','Probability exactly one is red',one),field('conditional','Both red given at least one red',rr/(rr+one))],'Use both colour orders for exactly one. Under the condition the denominator excludes the all-blue path.',dict(kind='without',R=R,B=B))
 ar,ab,br,bb=(2,3,4,2) if v==0 else (3,2,2,4);first=F(ar,ar+ab);j=first*F(br+1,br+bb+1);total=j+(1-first)*F(br,br+bb+1)
 quick('changing_samples',2,v,'A transfer changes the destination contents',f'<p>A has {ar} red and {ab} blue, B has {br} red and {bb} blue. Move a uniform counter from A to B, then draw uniformly from B. Find both selections red, the second selection red, and first red given second red.</p>',[field('joint','Probability both selections are red',j),field('total','Probability second selection is red',total),field('posterior','First red given second red',j/total)],'The destination contains one more counter at its draw. The red numerator depends on which colour was transferred.',dict(kind='transfer',ar=ar,ab=ab,br=br,bb=bb))
 R,B=(4,3) if v==0 else (3,2);N=R+B;rr=F(R,N)**2;rb=F(R,N)*F(B,N);bb=F(B,N)*F(B-1,N-1);totalB=rb+bb
 quick('changing_samples',3,v,'Replacement depends on the first colour',f'<p>A bag has {R} red and {B} blue counters. Return a red first counter but keep a blue first counter out. Draw again uniformly. Find the probabilities of equal colours, second blue, and first red given second blue.</p>',[field('same','Probability of equal colours',rr+bb),field('blue','Probability second is blue',totalB),field('posterior','First red given second blue',rb/totalB)],'The denominator on the second draw is unchanged after red and reduced after blue. Keep these separate branches.',dict(kind='conditional_replacement',R=R,B=B))
 R,B=2,2+v;N=R+B;at2=F(2,N*(N-1));at3=2*F(2*B,N*(N-1)*(N-2))
 quick('changing_samples',4,v,'A stopped path cannot have another draw',f'<p>Draw uniformly without replacement from {R} red and {B} blue until the second red appears. Find the chance of stopping on draw 3, by draw 3, and of a blue first draw given stopping on draw 3.</p>',[field('at_three','Probability of stopping on draw 3',at3),field('by_three','Probability of stopping by draw 3',at2+at3),field('conditional','First blue given stopping on draw 3',F(1,2))],'Only RBR and BRR reach their second red on draw 3. RR ends earlier and belongs only in the by-draw-three probability.',dict(kind='stop_two',R=R,B=B))

def fraction_typography(html):
 # Format only our own authored HTML. Do not touch attributes, model inputs or keys.
 pieces=re.split(r'(\\\([\s\S]*?\\\)|\\\[[\s\S]*?\\\]|<[^>]+>)',html)
 for i,part in enumerate(pieces):
  if part.startswith('<'):continue
  in_math=part.startswith((r'\(',r'\['))
  pieces[i]=re.sub(r'(?<![\w/])(-?\d+)\s*/\s*(\d+)(?![\w/])',lambda m:(r'\frac{'+m[1]+'}{'+m[2]+'}') if in_math else (r'\(\frac{'+m[1]+'}{'+m[2]+r'}\)'),part)
 return ''.join(pieces)
for prepared in lessons:
 prepared['ideas']=fraction_typography(prepared['ideas'])
 for example in prepared['examples']:
  for key in ['question','solution']:example[key]=fraction_typography(example[key])
for prepared in questions:
 for key in ['prompt_html','answer_html','solution_html','hint_html']:prepared[key]=fraction_typography(prepared[key])
